def transform(grid):
    h = len(grid)
    w = max(map(len, grid))
    seen = set()
    boxes = []
    for r in range(h):
        for c, value in enumerate(grid[r]):
            if value != 3 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < len(grid[ny])
                            and grid[ny][nx] == 3 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            boxes.append((min(y for y, x in cells), max(y for y, x in cells),
                          min(x for y, x in cells), max(x for y, x in cells)))

    out = [row[:] for row in grid]
    for r in range(h):
        for c, value in enumerate(grid[r]):
            if value != 2 or not any(r0 <= r <= r1 and c0 <= c <= c1
